import React from 'react';
import { render, screen } from '@testing-library/react';
import BeesGrow from './BeesGrow';

describe('BeesGrow', () => {
  test('should render without crashing', () => {
    render(<BeesGrow />);
    expect(screen.getByTestId('BeesGrowIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<BeesGrow variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Grow Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<BeesGrow variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Grow Vertical Logo')).toBeInTheDocument();
  });
  test('should render with a different colorType without crashing', () => {
    render(<BeesGrow colorType="onColorBg" />);
    expect(screen.getByTestId('BeesGrowIcon')).toBeInTheDocument();
  });
});
